mapper.select:
SELECT symbol, trade_date, open_p, high_p, low_p, close_p, volume
FROM daily_ohlcv
WHERE trade_date >= #{fromDate}
  AND symbol IN
  #{s}
ORDER BY symbol, trade_date

SELECT MAX(high_p) AS maxhigh, MIN(low_p) AS minlow
FROM daily_ohlcv
WHERE symbol = #{symbol} AND trade_date >= #{fromDate}

SELECT d.symbol AS symbol, MAX(d.high_p) AS maxhigh, MIN(d.low_p) AS minlow FROM daily_ohlcv d JOIN (
SELECT #{p.symbol} AS sym, #{p.fromDate} AS dt FROM dual
) f ON d.symbol = f.sym AND d.trade_date >= f.dt GROUP BY d.symbol
